var i=`0636-bamia-stew`;var n=`world-0636`;var a=`EG`;var o=`northern-africa`;var s=4;var r=63;var g={en:`Bamia Stew`,ua:`Тушкована бамія`};var l={en:`Bamia Stew is a Egypt classic prepared with lamb, yellow onion, garlic, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Тушкована бамія, страва кухні країни Єгипет зі складниками: ягнятина, жовта цибуля, часник, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var m=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`lamb`,570,`g`],[`yellow-onion`,140,`g`],[`sunflower-oil`,45,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`garlic`,4,`clove`],[`tomato`,420,`g`],[`tomato-paste`,45,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 40 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 40 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:40,i:[[`okra`,380,`g`],[`beef-stock`,650,`ml`],[`ground-coriander`,5,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`lemon-juice`,35,`ml`],[`cilantro`,20,`g`]]}];var d={slug:i,id:n,country:`EG`,region:o,servings:4,minutes:63,title:g,text:l,steps:m};export{a as country,d as default,n as id,r as minutes,o as region,s as servings,i as slug,m as steps,l as text,g as title};